head.script:
scwin.onpageload = function() {
    // 초기화
    scwin.initializeData();

    // 기본 데이터 조회
    scwin.searchUnitTests();
    console.log("시시시작")
    // 통계 조회
    scwin.loadStatistics();


};

/**
 * 데이터 초기화
 */
scwin.initializeData = function() {
    console.log("데이터 초기화 시작");

    // 검색 조건 초기화
    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", "10");

    // 페이징 정보 초기화
    scwin.allDataPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    scwin.pendingPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    scwin.runningPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    scwin.completedPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 검색 박스 표시 여부
    var searchComp = $p.getComponentById("searchComp_1");
    if (searchComp == undefined) {
        search_box.hide();
    }

    console.log("데이터 초기화 완료");
};

/**
 * 단위테스트 목록 조회
 */
scwin.searchUnitTests = function() {
    console.log("단위테스트 목록 조회 시작");

    // 검색 조건 설정
    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", "1000"); // 전체 데이터 조회

    // 서버 통신
    $c.sbm.execute($p, sbm_selectUnitTestList);
};

/**
 * 단위테스트 목록 조회 완료
 */
scwin.sbm_selectUnitTestList_submitdone = function(e) {
    console.log("단위테스트 목록 조회 완료", e);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    // 에러 처리
    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return false;
    }

    // 데이터 처리 - elData에서 접근
    var allData = elData.unitTestList || [];
    var totalCount = elData.totalCount || 0;

    console.log("전체 데이터:", allData.length, "개");
    console.log("총 개수:", totalCount);

    // 나머지 처리 로직...
    scwin.allDataPageInfo.data = allData;
    scwin.allDataPageInfo.totalCount = totalCount;

    // 상태별 데이터 필터링
    var pendingData = [];
    var runningData = [];
    var completedData = [];

    for (var i = 0; i < allData.length; i++) {
        var item = allData[i];
        if (item.testStatus === "PEN") {
            pendingData.push(item);
        } else if (item.testStatus === "RUN") {
            runningData.push(item);
        } else if (item.testStatus === "SUC" || item.testStatus === "FAI") {
            completedData.push(item);
        }
    }

    // 상태별 데이터 저장
    scwin.pendingPageInfo.data = pendingData;
    scwin.pendingPageInfo.totalCount = pendingData.length;
    scwin.runningPageInfo.data = runningData;
    scwin.runningPageInfo.totalCount = runningData.length;
    scwin.completedPageInfo.data = completedData;
    scwin.completedPageInfo.totalCount = completedData.length;

    // 그리드 데이터 업데이트
    scwin.updateGridData();

    // 카운트 업데이트
    scwin.updateCountLabels(totalCount, pendingData.length, runningData.length, completedData.length);

    // 페이징 업데이트
    scwin.updatePagination();
};

/**
 * 그리드 데이터 업데이트
 */
scwin.updateGridData = function() {
    console.log("그리드 데이터 업데이트 시작");

    try {
        // 전체 데이터 그리드 (첫 페이지)
        var allPageData = scwin.getPageData(scwin.allDataPageInfo.data, scwin.allDataPageInfo);
        dlt_unitTestVoList.setJSON(allPageData);

        // 상태별 그리드
        var pendingPageData = scwin.getPageData(scwin.pendingPageInfo.data, scwin.pendingPageInfo);
        dlt_pendingList.setJSON(pendingPageData);

        var runningPageData = scwin.getPageData(scwin.runningPageInfo.data, scwin.runningPageInfo);
        dlt_runningList.setJSON(runningPageData);

        var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
        dlt_completedList.setJSON(completedPageData);

        console.log("그리드 데이터 업데이트 완료");
    } catch (err) {
        console.error("그리드 데이터 업데이트 오류:", err);
    }
};

/**
 * 페이지별 데이터 추출
 */
scwin.getPageData = function(data, pageInfo) {
    if (!data || !pageInfo) {
        return [];
    }

    var startIndex = (pageInfo.currentPage - 1) * pageInfo.pageSize;
    var endIndex = startIndex + pageInfo.pageSize;
    return data.slice(startIndex, endIndex);
};

/**
 * 카운트 라벨 업데이트
 */
scwin.updateCountLabels = function(total, pending, running, completed) {
    try {
        spn_listCnt.setLabel(total);
        spn_pendingListCnt.setLabel(pending);
        spn_runningListCnt.setLabel(running);
        spn_completedListCnt.setLabel(completed);
    } catch (e) {
        console.error("카운트 라벨 업데이트 오류:", e);
    }
};

/**
 * 페이징 업데이트
 */
scwin.updatePagination = function() {
    try {
        // 전체 데이터 페이징
        var totalPages = Math.ceil(scwin.allDataPageInfo.totalCount / 10);
        if (totalPages > 0) {
            pgl_testList.setCount(totalPages);
            pgl_testList.setSelectedIndex(1);
        }

        // 상태별 페이징
        scwin.updateStatePagination(scwin.pendingPageInfo, pgl_pending);
        scwin.updateStatePagination(scwin.runningPageInfo, pgl_running);
        scwin.updateStatePagination(scwin.completedPageInfo, pgl_completed);

    } catch (e) {
        console.error("페이징 업데이트 오류:", e);
    }
};

/**
 * 상태별 페이징 업데이트
 */
scwin.updateStatePagination = function(pageInfo, paginationComponent) {
    var totalPages = Math.ceil(pageInfo.totalCount / pageInfo.pageSize);
    if (totalPages > 0) {
        paginationComponent.setCount(totalPages);
        paginationComponent.setSelectedIndex(pageInfo.currentPage);
    }
};

/**
 * 통계 조회
 */
scwin.loadStatistics = function() {
    console.log("통계 조회 시작");
    $c.sbm.execute($p, sbm_selectUnitTestStatistics);
};

/**
 * 통계 조회 완료
 */
scwin.sbm_selectUnitTestStatistics_submitdone = function(e) {
    console.log("통계 조회 완료", e);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        console.error("통계 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
        return;
    }

    // 통계 데이터 설정 - elData에서 접근
    dmp_statistics.setJSON(elData);

    console.log("통계 정보:", elData);
};

/**
 * 조회 버튼 클릭
 */
scwin.btn_search_onclick = function(e) {
    console.log("조회 버튼 클릭");

    // 페이지 초기화
    scwin.allDataPageInfo.currentPage = 1;
    scwin.pendingPageInfo.currentPage = 1;
    scwin.runningPageInfo.currentPage = 1;
    scwin.completedPageInfo.currentPage = 1;

    // 검색 실행
    scwin.searchUnitTests();
};

/**
 * 등록 버튼 클릭
 */
scwin.btn_register_onclick = function(e) {
    console.log("등록 버튼 클릭");

    // 데이터 초기화
    dmp_unitTestDetail.setEmptyValue();

    // 기본값 설정
    dmp_unitTestDetail.set("testStatus", "PEN");
    dmp_unitTestDetail.set("priority", "MEDIUM");
    dmp_unitTestDetail.set("testType", "NORMAL");
    dmp_unitTestDetail.set("taskId", "1");
    dmp_unitTestDetail.set("taskName", "ERP 시스템 고도화 프로젝트");
    dmp_unitTestDetail.set("assignee", "김개발");

    // 파일 목록 초기화
    dlt_upload.setJSON([]);
    dlt_attVoList.setJSON([]);

    // 등록 모드로 설정
    scwin.setFormMode("new");

    // 팝업 표시
    pop_overlay.show();

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("단위테스트 케이스 등록");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("단위테스트 케이스 등록");
            }, 50);
        }
    }, 50);

    // 미리보기 초기화
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

/**
 * 그리드 셀 클릭 이벤트
 */
scwin.grd_list_oncellclick = function(row, col, colId) {
    console.log("그리드 셀 클릭:", row, colId);

    var selectedData = dlt_unitTestVoList.getRowJSON(row);
    dmp_unitTestDetail.setJSON(selectedData);

    console.log("선택된 데이터:", selectedData);
};

/**
 * 그리드 셀 더블클릭 이벤트
 */
scwin.grd_list_oncelldblclick = function(row, col, colId) {
    console.log("그리드 셀 더블클릭:", row, colId);

    var selectedData = dlt_unitTestVoList.getRowJSON(row);
    dmp_unitTestDetail.setJSON(selectedData);

    // 상세 조회
    scwin.showDetailPopup("view");
};

/**
 * 대기 그리드 더블클릭
 */
scwin.pending_grd_oncelldblclick = function(row, col, colId) {
    var selectedData = dlt_pendingList.getRowJSON(row);
    dmp_unitTestDetail.setJSON(selectedData);
    scwin.showDetailPopup("view");
};

/**
 * 진행중 그리드 더블클릭
 */
scwin.running_grd_oncelldblclick = function(row, col, colId) {
    var selectedData = dlt_runningList.getRowJSON(row);
    dmp_unitTestDetail.setJSON(selectedData);
    scwin.showDetailPopup("view");
};

/**
 * 완료 그리드 더블클릭
 */
scwin.completed_grd_oncelldblclick = function(row, col, colId) {
    var selectedData = dlt_completedList.getRowJSON(row);
    dmp_unitTestDetail.setJSON(selectedData);
    scwin.showDetailPopup("view");
};

/**
 * 상세보기 팝업 표시
 */
scwin.showDetailPopup = function(mode) {
    console.log("상세보기 팝업 표시:", mode);

    // 팝업 표시
    pop_overlay.show();

    // 모드 설정
    scwin.setFormMode(mode);

    // 제목 설정
    setTimeout(function() {
        try {
            var title = mode === "view" ? "단위테스트 케이스 상세정보" : "단위테스트 케이스 수정";
            spn_popupTitle.setValue(title);
        } catch(e) {
            setTimeout(function() {
                var title = mode === "view" ? "단위테스트 케이스 상세정보" : "단위테스트 케이스 수정";
                spn_popupTitle.setValue(title);
            }, 50);
        }
    }, 50);

    // 파일 목록 로드
    scwin.loadFileList();
};

/**
 * 페이지 번호 클릭 이벤트
 */
scwin.pgl_testList_onclick = function(idx) {
    console.log("메인 페이지 클릭:", idx);

    scwin.allDataPageInfo.currentPage = idx;
    var pageData = scwin.getPageData(scwin.allDataPageInfo.data, scwin.allDataPageInfo);
    dlt_unitTestVoList.setJSON(pageData);
    pgl_testList.setSelectedIndex(idx);
};

scwin.pgl_pending_onclick = function(idx) {
    console.log("대기 페이지 클릭:", idx);

    scwin.pendingPageInfo.currentPage = idx;
    var pageData = scwin.getPageData(scwin.pendingPageInfo.data, scwin.pendingPageInfo);
    dlt_pendingList.setJSON(pageData);
    pgl_pending.setSelectedIndex(idx);
};

scwin.pgl_running_onclick = function(idx) {
    console.log("진행중 페이지 클릭:", idx);

    scwin.runningPageInfo.currentPage = idx;
    var pageData = scwin.getPageData(scwin.runningPageInfo.data, scwin.runningPageInfo);
    dlt_runningList.setJSON(pageData);
    pgl_running.setSelectedIndex(idx);
};

scwin.pgl_completed_onclick = function(idx) {
    console.log("완료 페이지 클릭:", idx);

    scwin.completedPageInfo.currentPage = idx;
    var pageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
    dlt_completedList.setJSON(pageData);
    pgl_completed.setSelectedIndex(idx);
};

/**
 * 저장 버튼 클릭
 */
scwin.btn_save_onclick = function(e) {
    console.log("저장 버튼 클릭");

    // 유효성 검사
    if (!scwin.validateForm()) {
        return;
    }

    // 파일이 있는지 확인
    var hasFiles = false;
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        hasFiles = mpd_html5Type.fileArray.length > 0;
    }

    if (hasFiles) {
        // 파일과 함께 등록
        scwin.saveTestWithFiles();
    } else {
        // 일반 등록
        $c.sbm.execute($p, sbm_insertUnitTest);
    }
};

/**
 * 폼 유효성 검사
 */
scwin.validateForm = function() {
    var testCaseName = dmp_unitTestDetail.get("testCaseName");
    var testTarget = dmp_unitTestDetail.get("testTarget");

    if (!testCaseName || testCaseName.trim() === "") {
        $c.win.alert("테스트케이스명을 입력해주세요.");
        return false;
    }

    if (!testTarget || testTarget.trim() === "") {
        $c.win.alert("테스트 대상을 입력해주세요.");
        return false;
    }

    return true;
};

/**
 * 파일과 함께 저장
 */
scwin.saveTestWithFiles = function() {
    console.log("파일과 함께 저장 시작");

    var formData = new FormData();

    // 테스트 케이스 데이터 추가
    var testData = dmp_unitTestDetail.getJSON();
    for (var key in testData) {
        if (testData[key] !== null && testData[key] !== undefined) {
            formData.append(key, testData[key]);
        }
    }

    // 파일 추가
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        var fileList = mpd_html5Type.fileArray;
        for (var i = 0; i < fileList.length; i++) {
            var realFile = fileList[i].file;
            formData.append("files", realFile);
        }
    }

    // 서버 전송
    fetch("/InsWebApp/UNIT001InsWithFiles.pwkjson", {
        method: "POST",
        body: formData
    })
    .then(function(res) { return res.json(); })
    .then(function(res) {
        console.log("파일과 함께 저장 완료:", res);

        $c.win.alert("등록되었습니다.");

        // 파일 목록 초기화
        dlt_upload.removeAll();
        if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
            mpd_html5Type.removeAllFiles();
        }

        // 팝업 닫기
        pop_overlay.hide();

        // 목록 새로고침
        scwin.searchUnitTests();
    })
    .catch(function(err) {
        console.error("파일과 함께 저장 실패:", err);
        $c.win.alert("등록 중 오류가 발생했습니다.");
    });
};

/**
 * 단위테스트 등록 완료
 */
scwin.sbm_insertUnitTest_submitdone = function(e) {
    console.log("단위테스트 등록 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return;
    }

    $c.win.alert("등록되었습니다.");
    pop_overlay.hide();
    scwin.searchUnitTests();
};

/**
 * 수정 버튼 클릭
 */
scwin.btn_popup_edit_onclick = function(e) {
    console.log("수정 버튼 클릭");
    scwin.setFormMode("edit");
};

/**
 * 수정 저장 버튼 클릭
 */
scwin.btn_update_onclick = function(e) {
    console.log("수정 저장 버튼 클릭");

    if (!scwin.validateForm()) {
        return;
    }

    var promise = $c.win.confirm("수정하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            $c.sbm.execute($p, sbm_updateUnitTest);
        }
    });
};

/**
 * 단위테스트 수정 완료
 */
scwin.sbm_updateUnitTest_submitdone = function(e) {
    console.log("단위테스트 수정 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return;
    }

    $c.win.alert("수정되었습니다.");
    scwin.setFormMode("view");
    scwin.searchUnitTests();
};

/**
 * 삭제 버튼 클릭
 */
scwin.btn_popup_delete_onclick = function(e) {
    console.log("삭제 버튼 클릭");

    var testCaseId = dmp_unitTestDetail.get("testCaseId");

    if (!testCaseId) {
        $c.win.alert("삭제할 테스트 케이스를 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("삭제하시겠습니까?\n관련된 파일도 함께 삭제됩니다.");
    promise.then(function(result) {
        if (result) {
            $c.sbm.execute($p, sbm_deleteUnitTest);
        }
    });
};

/**
 * 단위테스트 삭제 완료
 */
scwin.sbm_deleteUnitTest_submitdone = function(e) {
    console.log("단위테스트 삭제 완료:", e);

    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return;
    }

    $c.win.alert("삭제되었습니다.");
    pop_overlay.hide();
    scwin.searchUnitTests();
};

/**
 * 팝업 닫기
 */
scwin.esc_btn_onclick = function(e) {
    console.log("팝업 닫기");
    pop_overlay.hide();
};

/**
 * 초기화 버튼 클릭
 */
scwin.btn_reset_onclick = function(e) {
    console.log("초기화 버튼 클릭");

    dmp_unitTestDetail.setEmptyValue();
    dmp_unitTestDetail.set("testStatus", "PEN");
    dmp_unitTestDetail.set("priority", "MEDIUM");
    dmp_unitTestDetail.set("testType", "NORMAL");
    dmp_unitTestDetail.set("taskId", "1");
    dmp_unitTestDetail.set("taskName", "ERP 시스템 고도화 프로젝트");
    dmp_unitTestDetail.set("assignee", "김개발");

    scwin.setFormMode("new");
};

/**
 * 폼 모드 설정
 */
scwin.setFormMode = function(mode) {
    console.log("폼 모드 전환:", mode);

    if (mode === "edit") {
        // 수정 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 버튼 상태 변경
        btn_save.show();
        btn_popup_edit.hide();

    } else if (mode === "view") {
        // 조회 모드
        scwin.setFieldsReadOnly(true);
        scwin.setEditorMode(false);
        scwin.showFileUploadSection(false);

        // 버튼 상태 변경
        btn_save.hide();
        btn_popup_edit.show();
        btn_popup_delete.show();

    } else if (mode === "new") {
        // 등록 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 버튼 상태 변경
        btn_save.show();
        btn_popup_edit.hide();
        btn_popup_delete.hide();
    }
};

/**
 * 필드 읽기 전용 설정
 */
scwin.setFieldsReadOnly = function(readOnly) {
    try {
        var editableFields = [
            "inp_testCaseName",
            "inp_testTarget",
            "sel_testType",
            "sel_priority",
            "inp_requirements",
            "inp_duration"
        ];

        editableFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(readOnly);
            }
        });

        // 업무명과 담당자명은 항상 readOnly
        var alwaysReadOnlyFields = ["inp_taskName", "inp_assignee"];
        alwaysReadOnlyFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(true);
            }
        });

    } catch(e) {
        console.error("필드 읽기 전용 설정 오류:", e);
    }
};

/**
