        grp_testSteps_edit.show();
        grp_testSteps_view.hide();
        grp_expectedResult_edit.show();
        grp_expectedResult_view.hide();
        grp_actualResult_edit.show();
        grp_actualResult_view.hide();
        grp_notes_edit.show();
        grp_notes_view.hide();
    } else {
