        grp_description_edit.hide();
        grp_description_view.show();
        grp_precondition_edit.hide();
        grp_precondition_view.show();
        grp_testData_edit.hide();
        grp_testData_view.show();
        grp_testSteps_edit.hide();
        grp_testSteps_view.show();
