 * 일괄 상태 변경
 */
scwin.btn_batchStatusUpdate_onclick = function(e) {
    console.log("일괄 상태 변경");

    // 선택된 행들의 상태를 일괄 변경하는 기능
    $c.win.alert("일괄 상태 변경 기능은 준비 중입니다.");
};

/**
 * 테스트 실행 시작
 */
scwin.btn_startTest_onclick = function(e) {
    console.log("테스트 실행 시작");

    var testCaseId = dmp_unitTestDetail.get("testCaseId");

    if (!testCaseId) {
        $c.win.alert("실행할 테스트 케이스를 선택해주세요.");
        return;
    }

    var promise = $c.win.confirm("테스트를 실행하시겠습니까?");
    promise.then(function(result) {
        if (result) {
            scwin.updateTestStatus(testCaseId, "RUN");
        }
    });
};

/**
 * 테스트 완료 처리
 */
scwin.btn_completeTest_onclick = function(e) {
    console.log("테스트 완료 처리");

    var testCaseId = dmp_unitTestDetail.get("testCaseId");
    var actualResult = dmp_unitTestDetail.get("actualResult");
    var duration = dmp_unitTestDetail.get("duration");
    var notes = dmp_unitTestDetail.get("notes");

    if (!testCaseId) {
        $c.win.alert("완료할 테스트 케이스를 선택해주세요.");
        return;
    }

    if (!actualResult || actualResult.trim() === "") {
        $c.win.alert("실제 결과를 입력해주세요.");
        return;
    }

    // 성공/실패 선택 다이얼로그
    var promise = $c.win.confirm("테스트가 성공했습니까?\n확인: 성공, 취소: 실패");
    promise.then(function(result) {
        var status = result ? "SUC" : "FAI";
        scwin.updateTestResult(testCaseId, actualResult, status, duration, notes);
    });
};

console.log("Test1.xml 스크립트 로드 완료");
